{
  "case_id": "xsu_sg_009_medical_documentation_content",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret gengiver indholdet i afsnit 4.2 korrekt: varig funktionsnedsættelse med beskrivelse, udrednings- og behandlingsforløb, og de seks punkter, når oplysningerne findes i journalen eller anden lægefaglig dokumentation. Det gør ikke diagnose alene tilstrækkelig, gør ikke diagnose til et ubetinget krav, og det fremstiller ikke behandling som valgfri alternativer. Aktualitet nævnes ikke, men det er ikke en materiel fejl. Der er ingen væsentlig juridisk fejl."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Det første kritiske element kræver en relevant og aktuel beskrivelse af funktionsnedsættelsens art og grad. Svaret nævner ikke aktualitet (§ 37, stk. 4) og ikke 'art og grad'. Det siger kun, at funktionsnedsættelsen skal beskrives, og hvad den består i. Det fjerde element, at oplysningerne skal fremsendes, når de er tilgængelige, er kun delvist med. Svaret skriver 'bør', og det er svagere end 'skal fremsendes'."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvad den lægelige dokumentation skal beskrive, og indeholder ingen irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde. Der er ingen henvisning til vejledningen eller til SU-bekendtgørelsens § 37."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Svaret citerer ingen kilde, så kildens gyldighed kan ikke bedømmes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ingen angivne kilder, så det kan ikke vurderes, om passager understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Svaret tilføjer ingen væsentlig regel, betingelse eller retsvirkning uden støtte i vejledningens afsnit 4.2 og § 37. Alle punkter findes i afsnittet."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Forbeholdene er bevaret: 'hvis en er stillet', 'eventuelt planlagt behandling', 'hvis det er muligt at beskrive' og betingelsen om, at oplysningerne findes i journalen eller anden eksisterende lægefaglig dokumentation. Dokumentationsminimum ophæves ikke."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende. Først kommer de grundlæggende krav, derefter en liste over de konkrete oplysninger, der er betinget af tilgængelighed."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Vejledningen siger, at oplysningerne 'skal fremsendes', hvis de er tilgængelige i journalen eller anden eksisterende lægefaglig dokumentation. Svaret skriver, at dokumentationen 'bør' indeholde dem. Det svækker en pligt til en anbefaling. Resten af svaret bruger 'skal' korrekt."
    }
  },
  "xhaile_coverage": {
    "A39": {
      "label": "yes",
      "reason": "Svaret nævner 'diagnosen, hvis en er stillet' med det rette forbehold."
    },
    "A41": {
      "label": "yes",
      "reason": "Svaret nævner 'sygdoms- og behandlingsforløbet'."
    },
    "A42": {
      "label": "yes",
      "reason": "Svaret nævner behandlingsforløbet både i 'sygdoms- og behandlingsforløbet' og i 'udrednings- og behandlingsforløbet'."
    },
    "A45": {
      "label": "partial",
      "reason": "Svaret nævner 'igangværende og eventuelt planlagt behandling', så planlagt behandling er dækket med forbehold. Det er dog formuleret mindre præcist end 'hvis der er planlagt en', og 'bør' svækker kravet."
    },
    "A47": {
      "label": "yes",
      "reason": "Svaret nævner påvirkningen af erhvervsevnen 'hvis det er muligt at beskrive'."
    }
  },
  "overall_notes": "Indholdet svarer i store træk til afsnit 4.2 og bevarer forbeholdene. Svaret mangler dog aktualitet og 'art og grad', og det nedtoner 'skal fremsendes' til 'bør'. Der er ingen kildehenvisning, så C04 er not_met, og C05 og C06 er not_assessable."
}

